#!/usr/bin/env bash
# Update herdr-core-binary.nix with latest version from releases.herdr.dev

set -euo pipefail

SCRIPT_DIR="$(cd "$(dirname "${BASH_SOURCE[0]}")" && pwd)"
NIX_FILE="$SCRIPT_DIR/herdr-core-binary.nix"
MANIFEST_URL="https://releases.herdr.dev/core/latest.json"

manifest=$(curl -fsSL "$MANIFEST_URL")
version=$(echo "$manifest" | jq -r '.version')
generation=$(echo "$manifest" | jq -r '.generation')
echo "Fetching Herdr Core version: $version (generation $generation)"

{
  cat <<EOF
# Auto-generated by update-herdr-core.sh
# Binary distribution from https://releases.herdr.dev/core/latest.json
{
  version = "$version";
  generation = $generation;
  platforms = {
EOF

  echo "$manifest" | jq -r '
    .targets | to_entries[] |
    "    \"\(.key)\" = {\n      url = \"\(.value.url)\";\n      hash = \"sha256:\(.value.sha256)\";\n    };"
  '

  cat <<EOF
  };
}
EOF
} > "$NIX_FILE"

alejandra --quiet "$NIX_FILE"
echo "Updated $NIX_FILE"
